import{_ as s,o as t,c as n,a5 as i}from"./chunks/framework.Bt0SrEfo.js";const T=JSON.parse('{"title":"HTTP 协议演进:从 0.9 到 HTTP/3","description":"","frontmatter":{},"headers":[],"relativePath":"网络/2-http-evolution.md","filePath":"网络/2-http-evolution.md","lastUpdated":1790177750000}'),e={name:"网络/2-http-evolution.md"};function l(p,a,o,r,d,h){return t(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="http-协议演进-从-0-9-到-http-3" tabindex="-1">HTTP 协议演进:从 0.9 到 HTTP/3 <a class="header-anchor" href="#http-协议演进-从-0-9-到-http-3" aria-label="Permalink to &quot;HTTP 协议演进:从 0.9 到 HTTP/3&quot;">​</a></h1><h2 id="一、为什么-http-不断演进" tabindex="-1">一、为什么 HTTP 不断演进 <a class="header-anchor" href="#一、为什么-http-不断演进" aria-label="Permalink to &quot;一、为什么 HTTP 不断演进&quot;">​</a></h2><p>Web 应用越来越复杂:</p><ul><li>1995:一个 HTML 文档 + 几张图 → HTTP/0.9 够用</li><li>2000:CSS + JS + 多媒体 → HTTP/1.0 引入头</li><li>2010:单页应用、视频、API → HTTP/1.1 持久连接</li><li>2020:实时音视频、HTTP/2 + 微服务 → HTTP/3 解决队头阻塞</li></ul><p>每次演进都解决具体问题。</p><h2 id="二、http-0-9-1991" tabindex="-1">二、HTTP/0.9(1991) <a class="header-anchor" href="#二、http-0-9-1991" aria-label="Permalink to &quot;二、HTTP/0.9(1991)&quot;">​</a></h2><p><strong>极简设计</strong>:</p><ul><li>只有 GET 方法</li><li>响应只能是 HTML</li><li>没有头、没有状态码</li><li>连接关闭</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端:GET /</span></span>
<span class="line"><span>服务器:&lt;html&gt;&lt;body&gt;Hello World&lt;/body&gt;&lt;/html&gt;</span></span>
<span class="line"><span>连接关闭</span></span></code></pre></div><h2 id="三、http-1-0-1996-rfc-1945" tabindex="-1">三、HTTP/1.0(1996, RFC 1945) <a class="header-anchor" href="#三、http-1-0-1996-rfc-1945" aria-label="Permalink to &quot;三、HTTP/1.0(1996, RFC 1945)&quot;">​</a></h2><p><strong>核心改进</strong>:</p><ul><li>引入 POST、HEAD</li><li>引入 HTTP 头(<code>Content-Type</code>、<code>Authorization</code>、<code>User-Agent</code>)</li><li>引入状态码(200、404、500)</li><li>引入版本号</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /index.html HTTP/1.0</span></span>
<span class="line"><span>User-Agent: Mozilla/1.0</span></span>
<span class="line"><span>Accept: text/html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HTTP/1.0 200 OK</span></span>
<span class="line"><span>Content-Type: text/html</span></span>
<span class="line"><span>Content-Length: 123</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;html&gt;...&lt;/html&gt;</span></span></code></pre></div><p><strong>问题</strong>:</p><ul><li><strong>每个请求都要新建 TCP 连接</strong>(3 次握手 + 慢启动)</li><li>一个 HTML 引用 10 个 JS/CSS → 10 次连接建立</li></ul><h2 id="四、http-1-1-1999-rfc-2068-2616" tabindex="-1">四、HTTP/1.1(1999, RFC 2068 / 2616) <a class="header-anchor" href="#四、http-1-1-1999-rfc-2068-2616" aria-label="Permalink to &quot;四、HTTP/1.1(1999, RFC 2068 / 2616)&quot;">​</a></h2><p><strong>核心改进</strong>(解决 1.0 的连接问题):</p><h3 id="_4-1-持久连接-keep-alive" tabindex="-1">4.1 持久连接(Keep-Alive) <a class="header-anchor" href="#_4-1-持久连接-keep-alive" aria-label="Permalink to &quot;4.1 持久连接(Keep-Alive)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>默认 Connection: keep-alive</span></span>
<span class="line"><span>同一个 TCP 连接可以发多个请求</span></span></code></pre></div><p>但仍然有<strong>队头阻塞</strong>:一个响应回来前,后续请求不能发(同一个连接)。</p><h3 id="_4-2-管道化-pipelining" tabindex="-1">4.2 管道化(Pipelining) <a class="header-anchor" href="#_4-2-管道化-pipelining" aria-label="Permalink to &quot;4.2 管道化(Pipelining)&quot;">​</a></h3><p>理论上可以不等响应就发下一个请求,但<strong>实际浏览器很少启用</strong>(服务端要按顺序响应,实现复杂)。</p><h3 id="_4-3-其他改进" tabindex="-1">4.3 其他改进 <a class="header-anchor" href="#_4-3-其他改进" aria-label="Permalink to &quot;4.3 其他改进&quot;">​</a></h3><ul><li><code>Host</code> 头(支持虚拟主机)</li><li><code>Chunked</code> 传输编码(响应长度未知时分块)</li><li>缓存指令(<code>ETag</code>、<code>If-None-Match</code>、<code>Last-Modified</code>、<code>If-Modified-Since</code>)</li><li>范围请求(<code>Range</code> 头,断点续传)</li><li><code>Transfer-Encoding: chunked</code></li></ul><h2 id="五、http-2-2015-rfc-7540" tabindex="-1">五、HTTP/2(2015, RFC 7540) <a class="header-anchor" href="#五、http-2-2015-rfc-7540" aria-label="Permalink to &quot;五、HTTP/2(2015, RFC 7540)&quot;">​</a></h2><p><strong>目标</strong>:解决 HTTP/1.1 的队头阻塞,<strong>不改变 HTTP 语义</strong>。</p><h3 id="_5-1-二进制分帧" tabindex="-1">5.1 二进制分帧 <a class="header-anchor" href="#_5-1-二进制分帧" aria-label="Permalink to &quot;5.1 二进制分帧&quot;">​</a></h3><p>HTTP/1.x 是文本协议,HTTP/2 是<strong>二进制协议</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/2 帧格式:</span></span>
<span class="line"><span>+-----------------------------------------------+</span></span>
<span class="line"><span>| Length(24) | Type(8) | Flags(8) | Stream ID(32) |</span></span>
<span class="line"><span>+-----------------------------------------------+</span></span>
<span class="line"><span>| Payload (可变长度)                            |</span></span>
<span class="line"><span>+-----------------------------------------------+</span></span></code></pre></div><p>每个请求/响应被拆成多个帧,帧可以乱序发送,接收方按流 ID 重组。</p><h3 id="_5-2-多路复用-multiplexing" tabindex="-1">5.2 多路复用(Multiplexing) <a class="header-anchor" href="#_5-2-多路复用-multiplexing" aria-label="Permalink to &quot;5.2 多路复用(Multiplexing)&quot;">​</a></h3><p><strong>核心特性</strong>:一个连接上<strong>同时跑多个流</strong>,互不阻塞。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1:6 个 TCP 连接 × 1 个流 = 6 流(浏览器对同域最多 6 连接)</span></span>
<span class="line"><span>HTTP/2:1 个 TCP 连接 × 多流 = 几十到几百流</span></span></code></pre></div><p><strong>效果</strong>:</p><ul><li>消除应用层队头阻塞</li><li>减少 TCP 连接数(降低握手成本)</li><li>充分利用单连接带宽</li></ul><h3 id="_5-3-头部压缩-hpack" tabindex="-1">5.3 头部压缩(HPACK) <a class="header-anchor" href="#_5-3-头部压缩-hpack" aria-label="Permalink to &quot;5.3 头部压缩(HPACK)&quot;">​</a></h3><p>HTTP/1.x 每次请求都带完整头(几百字节到几 KB)。</p><p>HTTP/2 用 <strong>HPACK 算法</strong>:</p><ul><li>客户端和服务端维护&quot;头部表&quot;</li><li>重复头只发索引号</li><li>静态表(61 个常用头)+ 动态表(自定义)</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1:User-Agent: Mozilla/5.0 ... (200+ bytes)</span></span>
<span class="line"><span>HTTP/2:索引 23 → 索引引用 (1 byte)</span></span></code></pre></div><h3 id="_5-4-服务器推送-server-push" tabindex="-1">5.4 服务器推送(Server Push) <a class="header-anchor" href="#_5-4-服务器推送-server-push" aria-label="Permalink to &quot;5.4 服务器推送(Server Push)&quot;">​</a></h3><p>服务端可以<strong>主动</strong>推送资源给客户端(不需要客户端请求)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求:GET /index.html</span></span>
<span class="line"><span>服务器主动推送:/style.css、/script.js</span></span></code></pre></div><p><strong>现状</strong>:Chrome 已弃用(复杂、缓存难处理),实际项目很少用。</p><h3 id="_5-5-流量优先级" tabindex="-1">5.5 流量优先级 <a class="header-anchor" href="#_5-5-流量优先级" aria-label="Permalink to &quot;5.5 流量优先级&quot;">​</a></h3><p>每个流可以设优先级(1~256),高优先级帧优先发送。</p><h3 id="_5-6-http-2-的局限" tabindex="-1">5.6 HTTP/2 的局限 <a class="header-anchor" href="#_5-6-http-2-的局限" aria-label="Permalink to &quot;5.6 HTTP/2 的局限&quot;">​</a></h3><p><strong>TCP 队头阻塞</strong>:虽然应用层不阻塞,但 TCP 层丢包会重传,所有流都得等。<strong>HTTP/3 解决这个</strong>。</p><h2 id="六、http-3-2022-rfc-9114" tabindex="-1">六、HTTP/3(2022, RFC 9114) <a class="header-anchor" href="#六、http-3-2022-rfc-9114" aria-label="Permalink to &quot;六、HTTP/3(2022, RFC 9114)&quot;">​</a></h2><p><strong>核心改变</strong>:抛弃 TCP,基于 <strong>QUIC</strong>(Quick UDP Internet Connections)。</p><h3 id="_6-1-为什么不用-tcp" tabindex="-1">6.1 为什么不用 TCP? <a class="header-anchor" href="#_6-1-为什么不用-tcp" aria-label="Permalink to &quot;6.1 为什么不用 TCP?&quot;">​</a></h3><ul><li>TCP 改不动(改 TCP 协议需要操作系统升级,部署太慢)</li><li>TCP 队头阻塞问题难解决</li><li>TCP 三次握手慢</li></ul><h3 id="_6-2-quic-的优势" tabindex="-1">6.2 QUIC 的优势 <a class="header-anchor" href="#_6-2-quic-的优势" aria-label="Permalink to &quot;6.2 QUIC 的优势&quot;">​</a></h3><p><strong>1. 0-RTT / 1-RTT 握手</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP + TLS 1.2:3 次握手 + 2-RTT TLS = 5-RTT</span></span>
<span class="line"><span>TCP + TLS 1.3:3 次握手 + 1-RTT TLS = 4-RTT</span></span>
<span class="line"><span>QUIC:1-RTT(首次),0-RTT(已连接)</span></span></code></pre></div><p><strong>2. 独立流(解决队头阻塞)</strong></p><p>QUIC 是 UDP 上实现的可靠传输,<strong>每个流独立</strong>:</p><ul><li>流 A 丢包,只阻塞流 A</li><li>流 B 不受影响</li></ul><p><strong>3. 内置 TLS 1.3</strong></p><p>TLS 1.3 必须,无法禁用。</p><p><strong>4. 连接迁移(Connection Migration)</strong></p><p>传统 TCP 连接靠四元组(src IP、src port、dst IP、dst port)。手机切 WiFi 时,IP 变了,连接断开。</p><p>QUIC 用 <strong>64-bit Connection ID</strong> 标识连接,不依赖 IP,WiFi 切换无感。</p><p><strong>5. 更好的拥塞控制</strong></p><p>QUIC 应用层实现拥塞控制(BBR、Cubic),可以更快迭代。</p><h3 id="_6-3-http-3-现状" tabindex="-1">6.3 HTTP/3 现状 <a class="header-anchor" href="#_6-3-http-3-现状" aria-label="Permalink to &quot;6.3 HTTP/3 现状&quot;">​</a></h3><ul><li>Chrome / Firefox / Edge / Safari 都支持</li><li>Cloudflare、Fastly 等 CDN 默认开启</li><li><strong>Nginx 1.25+</strong> 支持(<code>http3 on</code> directive)</li><li>国内 CDN:腾讯云、阿里云都支持</li></ul><h3 id="_6-4-启用方式" tabindex="-1">6.4 启用方式 <a class="header-anchor" href="#_6-4-启用方式" aria-label="Permalink to &quot;6.4 启用方式&quot;">​</a></h3><p><strong>Nginx</strong>:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  http2 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  http3 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  quic_retry </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Alt-Svc </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;h3=&quot;:443&quot;; ma=86400&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 告知客户端 HTTP/3 可用</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>CDN 配置</strong>:</p><ul><li>Cloudflare:网络选项勾选 HTTP/3</li><li>阿里云 DCDN:协议配置启用 QUIC</li></ul><p><strong>注意事项</strong>:</p><ul><li>HTTP/3 用 UDP 443,<strong>防火墙要放行</strong></li><li><code>Alt-Svc</code> 头告诉浏览器 HTTP/3 可用,浏览器下次会尝试</li><li>失败 fallback 到 HTTP/2 或 HTTP/1.1</li></ul><h2 id="七、协议对比" tabindex="-1">七、协议对比 <a class="header-anchor" href="#七、协议对比" aria-label="Permalink to &quot;七、协议对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>HTTP/1.1</th><th>HTTP/2</th><th>HTTP/3</th></tr></thead><tbody><tr><td>协议层</td><td>TCP</td><td>TCP</td><td>QUIC(UDP)</td></tr><tr><td>多路复用</td><td>❌(应用层队头阻塞)</td><td>✅(同连接多流)</td><td>✅(独立流)</td></tr><tr><td>头部压缩</td><td>❌</td><td>✅(HPACK)</td><td>✅(QPACK)</td></tr><tr><td>握手</td><td>TCP + TLS 1.2</td><td>TCP + TLS 1.3</td><td>内置 TLS 1.3</td></tr><tr><td>队头阻塞</td><td>应用 + TCP 层</td><td>TCP 层</td><td>无</td></tr><tr><td>服务器推送</td><td>❌</td><td>✅(已弃用)</td><td>✅</td></tr><tr><td>0-RTT</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>连接迁移</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>部署难度</td><td>低</td><td>中</td><td>中</td></tr></tbody></table><h2 id="八、实战选型" tabindex="-1">八、实战选型 <a class="header-anchor" href="#八、实战选型" aria-label="Permalink to &quot;八、实战选型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新项目:直接上 HTTP/2(Nginx 自动),HTTP/3 视情况</span></span>
<span class="line"><span>老项目:升级 Nginx + 启用 HTTP/2,收益明显</span></span>
<span class="line"><span>高延迟网络(移动):HTTP/3 收益最大</span></span>
<span class="line"><span>弱网/丢包高:HTTP/3 优势明显</span></span>
<span class="line"><span>内网应用:HTTP/1.1 也够用</span></span></code></pre></div><h2 id="九、参考文献" tabindex="-1">九、参考文献 <a class="header-anchor" href="#九、参考文献" aria-label="Permalink to &quot;九、参考文献&quot;">​</a></h2><ul><li><a href="https://http2-explained.readthedocs.io/" target="_blank" rel="noreferrer">HTTP/2 详解</a> —— Daniel Stenberg</li><li><a href="https://http3-explained.haxx.se/" target="_blank" rel="noreferrer">HTTP/3 explained</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc9114" target="_blank" rel="noreferrer">RFC 9114 (HTTP/3)</a></li><li>《HTTP 权威指南》</li></ul>`,80)])])}const g=s(e,[["render",l]]);export{T as __pageData,g as default};
